756	// 清单结构（与数据文件无关的纯类型校验）；返回逐项原始记录
757	function parseManifestShape(raw: unknown, file: string): Array<Record<string, unknown>> {
758	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
759	    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
760	  }
761	  const o = raw as Record<string, unknown>;
762	  for (const k of Object.keys(o)) {
763	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
764	  }
765	  if (!Array.isArray(o.items)) {
766	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
767	  }
768	  const items = o.items as unknown[];
769	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期安排`);
770	
771	  const problems: string[] = [];
772	  const records: Array<Record<string, unknown> | null> = [];
773	  items.forEach((it, idx) => {
774	    const at = `第 ${idx + 1} 项`;
775	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
776	      problems.push(`${at} 必须是对象`);
777	      records.push(null);
778	      return;
779	    }
780	    const rec = it as Record<string, unknown>;
781	    for (const k of Object.keys(rec)) {
782	      if (k !== 'bookingId' && k !== 'start' && k !== 'end' && k !== 'resourceIds') {
783	        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、start、end、resourceIds）`);
784	      }
785	    }
786	    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
787	      problems.push(`${at} 的 bookingId 必须是非空字符串`);
788	    }
789	    if (typeof rec.start !== 'string' || rec.start === '') {
790	      problems.push(`${at} 的 start 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
791	    }
792	    if (typeof rec.end !== 'string' || rec.end === '') {
793	      problems.push(`${at} 的 end 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
794	    }
795	    if (!Array.isArray(rec.resourceIds)) {
796	      problems.push(`${at} 的 resourceIds 必须是非空数组（完整目标资源集合，整体替换原集合）`);
797	    } else {
798	      if (rec.resourceIds.length === 0) problems.push(`${at} 的 resourceIds 不能为空：资源集合整体替换，至少一个资源`);
799	      rec.resourceIds.forEach((rid, j) => {
800	        if (typeof rid !== 'string' || rid === '') {
801	          problems.push(`${at}.resourceIds[${j}] 必须是非空资源标识字符串`);
802	        }
803	      });
804	    }
805	    records.push(rec);
806	  });
807	  if (problems.length > 0) {
808	    throw new BizError(`改期清单 ${file} 内容非法，整批拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
809	  }
810	  return records as Array<Record<string, unknown>>;
811	}
812	
813	async function cmdRescheduleBatch(args: string[]): Promise<void> {
814	  const {values, positionals} = parseFlags(args, []);
815	  if (values.size > 0) {
816	    throw new UsageError(
817	      `reschedule-batch 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
818	    );
819	  }
820	  if (positionals.length !== 1) {
821	    throw new UsageError('用法: reschedule-batch <改期清单文件>');
822	  }
823	  const manifestFile = positionals[0];
824	
825	  const file = activeDataFile;
826	  const store = await loadStore(file);
827	  const records = parseManifestShape(await loadManifest(manifestFile), manifestFile);
828	
829	  // 第一阶段：逐项做与业务数据相关的基础校验，收集全部问题后一次性拒绝整批
830	  const problems: string[] = [];
831	  const seenBooking = new Map<string, number>(); // 标识 -> 首次出现的序号（1 基）
832	  const planned: Array<BatchTarget | null> = [];
833	  records.forEach((rec, idx) => {
834	    const at = `第 ${idx + 1} 项（${rec.bookingId as string}）`;
835	    let ok = true;
836	
837	    const firstAt = seenBooking.get(rec.bookingId as string);
838	    if (firstAt !== undefined) {
839	      problems.push(`${at} 预约标识重复：该标识已在第 ${firstAt} 项出现，每项预约在清单中只能出现一次`);
840	      ok = false;
841	    } else {
842	      seenBooking.set(rec.bookingId as string, idx + 1);
843	    }
844	
845	    const booking = store.bookings.find((b) => b.id === rec.bookingId);
846	    if (!booking) {
847	      problems.push(`${at} 未知预约标识: ${rec.bookingId}`);
848	      ok = false;
849	    } else if (booking.status === 'cancelled') {
850	      problems.push(`${at} 预约 ${booking.id} 已取消，不能改期`);
851	      ok = false;
852	    }
853	
854	    const rawRids = rec.resourceIds as string[];
855	    const dupes = rawRids.filter((id, j) => rawRids.indexOf(id) !== j);
856	    if (dupes.length > 0) problems.push(`${at} 资源重复指定: ${[...new Set(dupes)].join('、')}`);
857	    const unknown = [...new Set(rawRids)]
858	      .filter((id) => !store.resources.some((r) => r.id === id))
859	      .sort();
860	    if (unknown.length > 0) problems.push(`${at} 未知资源标识: ${unknown.join('、')}`);
861	
862	    let startMin = 0;
863	    let endMin = 0;
864	    let startParsed = false;
865	    let endParsed = false;
866	    try {
867	      startMin = parseDateTime(rec.start as string, `${at} 目标开始时间`);
868	      startParsed = true;
869	    } catch (err) {
870	      problems.push((err as BizError).message);
871	    }
872	    try {
873	      endMin = parseDateTime(rec.end as string, `${at} 目标结束时间`);
874	      endParsed = true;
875	    } catch (err) {
876	      problems.push((err as BizError).message);
877	    }
878	    if (startParsed && endParsed && endMin <= startMin) {
879	      problems.push(
880	        `${at} 目标结束时间必须晚于开始时间（开始: ${rec.start}，结束: ${rec.end}），允许跨日`,
881	      );
882	      ok = false;
883	    }
884	
885	    if (!ok || !booking) {
886	      planned.push(null);
887	      return;
888	    }
889	    planned.push({
890	      index: idx,
891	      booking,
892	      startRaw: rec.start as string,
893	      endRaw: rec.end as string,
894	      startMin,
895	      endMin,
896	      resourceIds: [...new Set(rawRids)].sort(),
897	    });
898	  });
899	
900	  if (problems.length > 0) {
901	    throw new BizError(`改期清单 ${manifestFile} 校验失败，整批拒绝（原有安排保持不变）：\n${problems.map((p) => `- ${p}`).join('\n')}`);
902	  }
903	  const targets = planned as BatchTarget[];
904	  const batchIds = new Set(targets.map((t) => t.booking.id));
905	
906	  // 第二阶段：对“整批完成后”的安排做校验。
907	  // 本批预约的旧占用一律不视为障碍（findConflicts 排除本批全部标识）；
908	  // 障碍只来自本批之外的有效预约，以及本批各项的目标安排彼此之间。
909	  const failures: BatchFailure[] = [];
910	  for (const t of targets) {
911	    const gaps = findCoverageGaps(store, t.resourceIds, t.startMin, t.endMin);
912	    const external = findConflicts(store, t.resourceIds, t.startMin, t.endMin).filter(
913	      (c) => !batchIds.has(c.booking.id),
914	    );
915	    const wanted = new Set(t.resourceIds);
916	    const internal: BatchFailure['internal'] = [];
917	    for (const o of targets) {
918	      if (o.index === t.index) continue;
919	      const overlap = o.startMin < t.endMin && t.startMin < o.endMin;
920	      if (!overlap) continue;
921	      const shared = o.resourceIds.filter((id) => wanted.has(id)).sort();
922	      if (shared.length > 0) internal.push({other: o, shared});
923	    }
