1099	async function cmdCreateSeries(args: string[]): Promise<void> {
1100	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end', 'count'], ['resource']);
1101	  if (positionals.length > 0) throw new UsageError(`create-series 不接受位置参数: ${positionals.join(' ')}`);
1102	
1103	  const resourceArgs = values.get('resource');
1104	  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
1105	  const startRaw = requireFlag(values, 'start');
1106	  const endRaw = requireFlag(values, 'end');
1107	  const count = parseOccurrences(requireFlag(values, 'count'));
1108	
1109	  const file = activeDataFile;
1110	  const store = await loadStore(file);
1111	
1112	  const ids = resolveResourceIds(store, resourceArgs);
1113	  const startMin = parseDateTime(startRaw, '首项开始时间');
1114	  const endMin = parseDateTime(endRaw, '首项结束时间');
1115	  if (endMin <= startMin) {
1116	    throw new BizError(`首项结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
1117	  }
1118	
1119	  // 先展开全部成员时间（含跨月、闰日、跨年、年份范围校验）
1120	  const members = planWeeklyMembers(startMin, endMin, count);
1121	
1122	  // 逐项校验：开放覆盖、与既有有效预约冲突、与系列内其他成员冲突
1123	  const failures: MemberFailure[] = [];
1124	  for (let i = 0; i < members.length; i++) {
1125	    const m = members[i];
1126	    const gaps = findCoverageGaps(store, ids, m.startMin, m.endMin);
1127	    const conflicts = findConflicts(store, ids, m.startMin, m.endMin);
1128	    const internal: Array<{other: PlannedMember; otherIndex: number}> = [];
1129	    for (let j = 0; j < members.length; j++) {
1130	      if (j === i) continue;
1131	      const o = members[j];
1132	      if (o.startMin < m.endMin && m.startMin < o.endMin) {
1133	        internal.push({other: o, otherIndex: j});
1134	      }
1135	    }
1136	    if (gaps.length > 0 || conflicts.length > 0 || internal.length > 0) {
1137	      failures.push({index: i, startRaw: m.startRaw, endRaw: m.endRaw, gaps, conflicts, internal});
1138	    }
1139	  }
1140	
1141	  if (failures.length > 0) {
1142	    // 按发生顺序报告所有失败项；任一项不满足则整批失败，不分配任何标识、不写文件
1143	    const blocks = failures.map((f) => {
1144	      const lines = [`第 ${f.index + 1} 项 ${f.startRaw} → ${f.endRaw}：`];
1145	      if (f.gaps.length > 0) {
1146	        lines.push('  开放不足资源:');
1147	        for (const {id, r} of f.gaps) lines.push(`    - ${id}（${r.name}）`);
1148	      }
1149	      if (f.conflicts.length > 0) {
1150	        lines.push('  与以下既有预约冲突:');
1151	        for (const c of f.conflicts) {
1152	          lines.push(
1153	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
1154	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
1155	          );
1156	        }
1157	      }
1158	      if (f.internal.length > 0) {
1159	        lines.push('  与系列内其他成员冲突:');
1160	        for (const x of f.internal) {
1161	          lines.push(
1162	            `    - 第 ${x.otherIndex + 1} 项（${x.other.startRaw} → ${x.other.endRaw}）：双方时间重叠`,
1163	          );
1164	        }
1165	      }
1166	      return lines.join('\n');
1167	    });
1168	    throw new BizError(
1169	      `系列创建失败：共 ${failures.length} 项不满足条件（按发生顺序），整批未创建：\n${blocks.join('\n')}`,
1170	    );
1171	  }
1172	
1173	  // 全部验证通过：分配一个系列标识与每项预约标识，一次性落盘。
1174	  // 标识在此刻才生成，任何失败都不会推进计数。
1175	  store.seriesSeq += 1;
1176	  const seriesId = `S${String(store.seriesSeq).padStart(4, '0')}`;
1177	  const assigned: Array<{id: string; m: PlannedMember}> = [];
1178	  for (const m of members) {
