1185	      end: m.endRaw,
1186	      status: 'active',
1187	      seriesId,
1188	    });
1189	    assigned.push({id, m});
1190	  }
1191	  store.series.push({id: seriesId});
1192	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
1193	  store.series.sort((a, b) => a.id.localeCompare(b.id));
