1196	  console.log(`已创建按周重复系列 ${seriesId}（共 ${count} 项，每周一次，全部成员使用相同资源）`);
1197	  console.log(`  资源: ${formatResourceIds(store, ids)}`);
1198	  assigned.forEach(({id, m}, i) => {
