1369	  const globalArgs = splitGlobalArgs(process.argv.slice(2));
1370	  activeDataFile = globalArgs.dataFile;
1371	
1372	  if (globalArgs.help || globalArgs.rest.length === 0) {
1373	    process.stdout.write(HELP_TEXT);
