1380	      await cmdAddResource(commandArgs);
1381	      break;
1382	    case 'list-resources':
1383	      await cmdListResources(commandArgs);
1384	      break;
1385	    case 'create-booking':
1386	      await cmdCreateBooking(commandArgs);
1387	      break;
1388	    case 'reschedule-booking':
1389	      await cmdRescheduleBooking(commandArgs);
1390	      break;
